import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { expect, test } from "vitest";

/**
 * Nuxt Icon's client bundle (generated by `nuxi prepare`): the icons found
 * in the sources.
 */
const bundle = await import(pathToFileURL(resolve(".nuxt/nuxt-icon-client-bundle.mjs")).href) as {
  init: (addIcon: (name: string) => void) => void;
};

test("the style sheet has the CSS of every icon found in the sources (else: node scripts/icon-css.mjs)", () => {
  const css = readFileSync(resolve("app/assets/css/icons.css"), "utf8");
  const missing: string[] = [];
  bundle.init((name) => {
    if (!css.includes(`:where(.i-${name.replace(":", "\\:")})`)) missing.push(name);
  });
  expect(missing).toEqual([]);
});
